1	// Python's `int(str)` for base 10.
2	//
3	// CPython first runs _PyUnicode_TransformDecimalAndSpaceToASCII, which folds
4	// every Unicode-whitespace code point to U+0020 and every category-Nd digit to
5	// its ASCII counterpart, then hands the result to the ASCII integer parser.
6	
7	import { codePoints } from './pycodec.mjs';
8	import { decimalValue, isPySpace } from './unidata.mjs';
9	
10	export class IntParseError extends Error {}
11	
12	// Digits, optionally separated by single underscores that must sit between
13	// digits.  This encodes "no leading/trailing/doubled underscore" in one place.
14	const DIGITS = /^[0-9](?:_?[0-9])*$/;
15	
16	export function pyInt(s) {
17	  const cps = codePoints(s);
18	  let folded = '';
19	  for (let i = 0; i < cps.length; i++) {
20	    const cp = cps[i];
21	    if (isPySpace(cp)) {
22	      folded += ' ';
23	      continue;
24	    }
25	    const d = decimalValue(cp);
26	    if (d >= 0) {
27	      folded += String(d);
28	      continue;
29	    }
30	    // Everything else survives untouched and will be rejected below, unless it
31	    // is a sign or an underscore.
32	    if (cp >= 0xd800 && cp <= 0xdfff) folded += String.fromCharCode(cp);
33	    else folded += String.fromCodePoint(cp);
34	  }
35	
36	  // Leading / trailing ASCII whitespace is ignored by the integer parser.
37	  let body = folded.replace(/^[ \t\n\v\f\r]+/, '').replace(/[ \t\n\v\f\r]+$/, '');
38	
39	  let negative = false;
40	  if (body.startsWith('+')) {
41	    body = body.slice(1);
42	  } else if (body.startsWith('-')) {
43	    negative = true;
44	    body = body.slice(1);
45	  }
46	
47	  if (!DIGITS.test(body)) throw new IntParseError('invalid literal');
48	
49	  const value = BigInt(body.replace(/_/g, ''));
50	  return negative ? -value : value;
51	}
