53	// argparse's `_negative_number_matcher`, i.e. r'^-\d+$|^-\d*\.\d+$' with
54	// Python's Unicode-aware \d (= category Nd).
55	export function looksLikeNegativeNumber(s) {
56	  const cps = codePoints(s);
57	  if (cps.length < 2 || cps[0] !== 0x2d) return false;
58	  let shape = '';
59	  for (let i = 1; i < cps.length; i++) {
60	    if (decimalValue(cps[i]) >= 0) shape += 'd';
61	    else if (cps[i] === 0x2e) shape += '.';
62	    else return false;
63	  }
64	  return /^d+$/.test(shape) || /^d*\.d+$/.test(shape);
65	}
