1	// UTF-8 / ASCII codecs with CPython semantics, including the
2	// `surrogateescape` and `replace` error handlers.
3	//
4	// A Python `str` is modelled as a JS string; because lone surrogates matter
5	// here, positions are always counted in code points via `codePoints()`.
6	
7	import { PyUnicodeEncodeError } from './pyerrors.mjs';
8	
9	// Split a JS string into code points.  Unpaired surrogates survive as their own
10	// single-unit entries, which is exactly what `surrogateescape` produces.
11	export function codePoints(s) {
12	  const out = [];
13	  for (let i = 0; i < s.length; i++) {
14	    const c = s.charCodeAt(i);
15	    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
16	      const d = s.charCodeAt(i + 1);
17	      if (d >= 0xdc00 && d <= 0xdfff) {
18	        out.push(0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00));
19	        i++;
20	        continue;
21	      }
22	    }
23	    out.push(c);
24	  }
25	  return out;
26	}
27	
28	export function fromCodePoints(cps) {
29	  let s = '';
30	  for (let i = 0; i < cps.length; i++) {
31	    const cp = cps[i];
32	    if (cp >= 0xd800 && cp <= 0xdfff) s += String.fromCharCode(cp);
33	    else s += String.fromCodePoint(cp);
34	  }
35	  return s;
36	}
37	
38	function isSurrogate(cp) {
39	  return cp >= 0xd800 && cp <= 0xdfff;
40	}
41	
42	// Python `str.encode()` (utf-8, strict).  Lone surrogates raise, and adjacent
43	// bad code points are reported as one range.
44	export function encodeUtf8(s) {
45	  const cps = codePoints(s);
46	  const out = [];
47	  for (let i = 0; i < cps.length; i++) {
48	    const cp = cps[i];
49	    if (cp < 0x80) {
50	      out.push(cp);
51	    } else if (cp < 0x800) {
52	      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
53	    } else if (isSurrogate(cp)) {
54	      let end = i + 1;
55	      while (end < cps.length && isSurrogate(cps[end])) end++;
56	      throw new PyUnicodeEncodeError('utf-8', cps, i, end, 'surrogates not allowed');
57	    } else if (cp < 0x10000) {
58	      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
59	    } else {
60	      out.push(
61	        0xf0 | (cp >> 18),
62	        0x80 | ((cp >> 12) & 0x3f),
63	        0x80 | ((cp >> 6) & 0x3f),
64	        0x80 | (cp & 0x3f),
65	      );
66	    }
67	  }
68	  return out;
69	}
70	
71	// Python `str.encode('ascii')` (strict).
72	export function encodeAscii(s) {
73	  const cps = codePoints(s);
74	  const out = [];
75	  for (let i = 0; i < cps.length; i++) {
76	    const cp = cps[i];
77	    if (cp < 0x80) {
78	      out.push(cp);
79	      continue;
80	    }
81	    let end = i + 1;
82	    while (end < cps.length && cps[end] >= 0x80) end++;
83	    throw new PyUnicodeEncodeError('ascii', cps, i, end, 'ordinal not in range(128)');
84	  }
85	  return out;
86	}
