88	// Shared UTF-8 decoder.  On malformed input it reports the "maximal subpart"
89	// (the longest prefix of a would-be sequence), which is how both CPython and
90	// V8 group decoding errors.
91	function decodeUtf8(bytes, emitChar, emitError) {
92	  const n = bytes.length;
93	  let i = 0;
94	  while (i < n) {
95	    const b0 = bytes[i];
96	    if (b0 < 0x80) {
97	      emitChar(b0);
98	      i++;
99	      continue;
100	    }
101	    let need = 0;
102	    let lo = 0x80;
103	    let hi = 0xbf;
104	    let acc = 0;
105	    if (b0 >= 0xc2 && b0 <= 0xdf) {
106	      need = 1;
107	      acc = b0 & 0x1f;
108	    } else if (b0 >= 0xe0 && b0 <= 0xef) {
109	      need = 2;
110	      acc = b0 & 0x0f;
111	      if (b0 === 0xe0) lo = 0xa0;
112	      else if (b0 === 0xed) hi = 0x9f;
113	    } else if (b0 >= 0xf0 && b0 <= 0xf4) {
114	      need = 3;
115	      acc = b0 & 0x07;
116	      if (b0 === 0xf0) lo = 0x90;
117	      else if (b0 === 0xf4) hi = 0x8f;
118	    } else {
119	      emitError([b0]);
120	      i++;
121	      continue;
122	    }
123	    let j = i + 1;
124	    let ok = true;
125	    for (let k = 0; k < need; k++) {
126	      const min = k === 0 ? lo : 0x80;
127	      const max = k === 0 ? hi : 0xbf;
128	      if (j >= n) {
129	        ok = false;
130	        break;
131	      }
132	      const b = bytes[j];
133	      if (b < min || b > max) {
134	        ok = false;
135	        break;
136	      }
137	      acc = (acc << 6) | (b & 0x3f);
138	      j++;
139	    }
140	    if (!ok) {
141	      emitError(bytes.slice(i, j));
142	      i = j;
143	      continue;
144	    }
145	    emitChar(acc);
146	    i = j;
147	  }
148	}
149	
150	// Python `bytes.decode('utf-8', 'surrogateescape')`: each undecodable byte
151	// becomes U+DC00+byte.
152	export function decodeUtf8Surrogateescape(bytes) {
153	  const cps = [];
154	  decodeUtf8(
155	    bytes,
156	    (cp) => cps.push(cp),
157	    (bad) => {
158	      for (let i = 0; i < bad.length; i++) cps.push(0xdc00 + bad[i]);
159	    },
160	  );
161	  return fromCodePoints(cps);
162	}
163	
164	// Python `bytes.decode('utf-8', 'replace')`: one U+FFFD per maximal subpart.
165	// Used only to cross-check our recovered argv against `process.argv`.
166	export function decodeUtf8Replace(bytes) {
167	  const cps = [];
168	  decodeUtf8(
169	    bytes,
170	    (cp) => cps.push(cp),
171	    () => cps.push(0xfffd),
172	  );
173	  return fromCodePoints(cps);
174	}
