1	// Minimal slices of the Unicode character database that CPython relies on.
2	//
3	// * `Py_UNICODE_ISSPACE` -- the charset used by `str.strip()`/`str.rstrip()`
4	//   with no argument, and by `int()` when it trims its operand.
5	// * category Nd (decimal digits) plus each digit's numeric value, used by
6	//   `int()` to accept e.g. Arabic-Indic or fullwidth digits.
7	// * `Py_UNICODE_ISPRINTABLE`, used by `repr()` of a str.
8	
9	// Exactly the code points for which CPython's Py_UNICODE_ISSPACE is true.
10	const SPACE_SET = new Set([
11	  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20,
12	  0x85, 0xa0, 0x1680,
13	  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007,
14	  0x2008, 0x2009, 0x200a,
15	  0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
16	]);
17	
18	export function isPySpace(cp) {
19	  return SPACE_SET.has(cp);
20	}
21	
22	// Start code point of every 10-long run of category-Nd characters.  Every Nd
23	// block in the UCD is exactly ten consecutive code points whose numeric values
24	// run 0..9, so `cp - start` is the digit value.
25	const ND_STARTS = [
26	  48, 1632, 1776, 1984, 2406, 2534, 2662, 2790, 2918, 3046, 3174, 3302,
27	  3430, 3558, 3664, 3792, 3872, 4160, 4240, 6112, 6160, 6470, 6608, 6784,
28	  6800, 6992, 7088, 7232, 7248, 42528, 43216, 43264, 43472, 43504, 43600,
29	  44016, 65296, 66720, 68912, 69734, 69872, 69942, 70096, 70384, 70736,
30	  70864, 71248, 71360, 71472, 71904, 72016, 72784, 73040, 73120, 73552,
31	  92768, 92864, 93008, 120782, 120792, 120802, 120812, 120822, 123200,
32	  123632, 124144, 125264, 130032,
33	];
34	
35	// Numeric value 0..9 of a decimal digit code point, or -1 when `cp` is not Nd.
36	export function decimalValue(cp) {
37	  let lo = 0;
38	  let hi = ND_STARTS.length - 1;
39	  let best = -1;
40	  while (lo <= hi) {
41	    const mid = (lo + hi) >> 1;
42	    if (ND_STARTS[mid] <= cp) {
43	      best = ND_STARTS[mid];
44	      lo = mid + 1;
45	    } else {
46	      hi = mid - 1;
47	    }
48	  }
49	  if (best < 0) return -1;
50	  const delta = cp - best;
51	  return delta < 10 ? delta : -1;
52	}
