54	const NONPRINTABLE = /[\p{C}\p{Zl}\p{Zp}\p{Zs}]/u;
55	
56	// CPython: everything in Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs is non-printable,
57	// except U+0020 which is deliberately treated as printable.
58	export function isPrintable(cp) {
59	  if (cp === 0x20) return true;
60	  if (cp >= 0xd800 && cp <= 0xdfff) return false;
61	  return !NONPRINTABLE.test(String.fromCodePoint(cp));
62	}
