1	// Python `repr()` for `bytes` and `str`.
2	
3	import { codePoints } from './pycodec.mjs';
4	import { isPrintable } from './unidata.mjs';
5	
6	const SQ = 0x27; // '
7	const DQ = 0x22; // "
8	const BS = 0x5c; // \
9	
10	function hex(n, width) {
11	  let s = n.toString(16);
12	  while (s.length < width) s = '0' + s;
13	  return s;
14	}
15	
16	function pickQuote(units) {
17	  let hasSingle = false;
18	  let hasDouble = false;
19	  for (let i = 0; i < units.length; i++) {
20	    if (units[i] === SQ) hasSingle = true;
21	    else if (units[i] === DQ) hasDouble = true;
22	  }
23	  return hasSingle && !hasDouble ? DQ : SQ;
24	}
25	
26	// repr(b'...')
27	export function bytesRepr(bytes) {
28	  const quote = pickQuote(bytes);
29	  let out = 'b' + String.fromCharCode(quote);
30	  for (let i = 0; i < bytes.length; i++) {
31	    const c = bytes[i];
32	    if (c === quote || c === BS) out += '\\' + String.fromCharCode(c);
33	    else if (c === 0x09) out += '\\t';
34	    else if (c === 0x0a) out += '\\n';
35	    else if (c === 0x0d) out += '\\r';
36	    else if (c < 0x20 || c >= 0x7f) out += '\\x' + hex(c, 2);
37	    else out += String.fromCharCode(c);
38	  }
39	  return out + String.fromCharCode(quote);
40	}
41	
42	// repr('...')
43	export function strRepr(s) {
44	  const cps = codePoints(s);
45	  const quote = pickQuote(cps);
46	  let out = String.fromCharCode(quote);
47	  for (let i = 0; i < cps.length; i++) {
48	    const c = cps[i];
49	    if (c === quote || c === BS) out += '\\' + String.fromCharCode(c);
50	    else if (c === 0x09) out += '\\t';
51	    else if (c === 0x0a) out += '\\n';
52	    else if (c === 0x0d) out += '\\r';
53	    else if (c < 0x20 || c === 0x7f) out += '\\x' + hex(c, 2);
54	    else if (c < 0x7f) out += String.fromCharCode(c);
55	    else if (isPrintable(c)) out += String.fromCodePoint(c);
56	    else if (c <= 0xff) out += '\\x' + hex(c, 2);
57	    else if (c <= 0xffff) out += '\\u' + hex(c, 4);
58	    else out += '\\U' + hex(c, 8);
59	  }
60	  return out + String.fromCharCode(quote);
61	}
