1	// Primitives for Python-style byte strings, modelled as plain Arrays of
2	// integers in 0..255.
3	
4	export function concat(a, b) {
5	  const out = a.slice();
6	  for (let i = 0; i < b.length; i++) out.push(b[i]);
7	  return out;
8	}
9	
10	export function equal(a, b) {
11	  if (a.length !== b.length) return false;
12	  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
13	  return true;
14	}
