16	// Python `bytes[start:]`-style slice with negative index support.
17	export function slice(a, start, stop) {
18	  const n = a.length;
19	  let s = start === undefined ? 0 : start;
20	  let e = stop === undefined ? n : stop;
21	  if (s < 0) s += n;
22	  if (e < 0) e += n;
23	  if (s < 0) s = 0;
24	  if (e > n) e = n;
25	  if (e < s) e = s;
26	  return a.slice(s, e);
27	}
