36	// Python `bytes.rstrip()` with no argument: ASCII whitespace only
37	// (space, \t, \n, \v, \f, \r).
38	const ASCII_SPACE = new Set([0x20, 0x09, 0x0a, 0x0b, 0x0c, 0x0d]);
39	
40	export function rstripAsciiSpace(a) {
41	  let end = a.length;
42	  while (end > 0 && ASCII_SPACE.has(a[end - 1])) end--;
43	  return a.slice(0, end);
44	}
45	
46	export function repeatByte(byte, count) {
47	  const out = [];
48	  for (let i = 0; i < count; i++) out.push(byte);
49	  return out;
50	}
51	
52	// Python `int.from_bytes(v, 'big')`.
53	export function intFromBytesBig(a) {
54	  let acc = 0n;
55	  for (let i = 0; i < a.length; i++) acc = (acc << 8n) | BigInt(a[i]);
56	  return acc;
57	}
