59	// Bytes of an all-ASCII JS string, without validation.
60	export function fromAsciiLiteral(s) {
61	  const out = [];
62	  for (let i = 0; i < s.length; i++) out.push(s.charCodeAt(i) & 0xff);
63	  return out;
64	}
