66	// Interpret a byte string as latin-1 text (only used to build JS strings out of
67	// pure-ASCII base58 output for printing).
68	export function toLatin1String(a) {
69	  let s = '';
70	  for (let i = 0; i < a.length; i++) s += String.fromCharCode(a[i]);
71	  return s;
72	}
