10	export class PyException extends Error {
11	  constructor(typeName, message) {
12	    super(`${typeName}: ${message}`);
13	    this.typeName = typeName;
14	    this.pyMessage = message;
15	    // Outermost frame first, matching the order Python prints them.
16	    this.frames = [];
17	  }
18	
19	  exceptionLine() {
20	    return `${this.typeName}: ${this.pyMessage}`;
21	  }
22	}
