30	// Mirrors CPython's UnicodeEncodeError.__str__: a single offending code point
31	// is rendered with its \x/\u/\U escape, a run collapses to "characters in
32	// position start-end".
33	export function formatEncodeError(encoding, codePoints, start, end, reason) {
34	  if (start < codePoints.length && end === start + 1) {
35	    const bad = codePoints[start];
36	    let esc;
37	    if (bad <= 0xff) esc = '\\x' + hex(bad, 2);
38	    else if (bad <= 0xffff) esc = '\\u' + hex(bad, 4);
39	    else esc = '\\U' + hex(bad, 8);
40	    return `'${encoding}' codec can't encode character '${esc}' in position ${start}: ${reason}`;
41	  }
42	  return `'${encoding}' codec can't encode characters in position ${start}-${end - 1}: ${reason}`;
43	}
44	
45	export class PyUnicodeEncodeError extends PyException {
46	  constructor(encoding, codePoints, start, end, reason) {
47	    super('UnicodeEncodeError', formatEncodeError(encoding, codePoints, start, end, reason));
48	    this.encoding = encoding;
49	    this.start = start;
50	    this.end = end;
51	    this.reason = reason;
52	  }
53	}
54	
55	export function withFrames(err, frames) {
56	  err.frames = frames.concat(err.frames);
57	  return err;
58	}
59	
60	export function formatTraceback(err) {
61	  let out = 'Traceback (most recent call last):\n';
62	  for (const f of err.frames) {
63	    out += `  File "${f.file}", line ${f.line}, in ${f.name}\n`;
64	  }
65	  out += err.exceptionLine() + '\n';
66	  return out;
67	}
