1	// Python `str.rstrip()` with no argument: strips the Unicode whitespace set.
2	
3	import { codePoints, fromCodePoints } from './pycodec.mjs';
4	import { isPySpace } from './unidata.mjs';
5	
6	export function rstrip(s) {
7	  const cps = codePoints(s);
8	  let end = cps.length;
9	  while (end > 0 && isPySpace(cps[end - 1])) end--;
10	  return end === cps.length ? s : fromCodePoints(cps.slice(0, end));
11	}
