// Differential fuzzer: /workspace/dataset/test19_executable  vs  node <CAND>
//
// Every argv element is modelled as an array of raw bytes and handed to both
// programs through bash ANSI-C quoting, so we can exercise invalid UTF-8 too.
//
//   node /tmp/fuzz1.mjs [--cand /tmp/cand1/test19.mjs] [--seed 12345] [--n 460]

import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test19_executable';

function argOf(name, dflt) {
  const i = process.argv.indexOf(name);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : dflt;
}
const CAND = argOf('--cand', '/tmp/cand1/test19.mjs');
const SEED = Number(argOf('--seed', '20260810'));
const TARGET = Number(argOf('--n', '460'));
const TIMEOUT_MS = Number(argOf('--timeout', '15000'));
const VERBOSE = process.argv.includes('--verbose');

// ---------------------------------------------------------------- prng
let _s = SEED >>> 0;
function rnd() {
  _s = (_s + 0x6d2b79f5) >>> 0;
  let t = _s;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
const ri = (n) => Math.floor(rnd() * n);
const pick = (a) => a[ri(a.length)];

// ---------------------------------------------------------------- bytes
function utf8(str) {
  const out = [];
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 63));
    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    else
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 63),
        0x80 | ((cp >> 6) & 63),
        0x80 | (cp & 63),
      );
  }
  return out;
}
const RAW = Symbol('raw');
const raw = (bytes) => ({ [RAW]: bytes });
const toBytes = (v) => (v && v[RAW] ? v[RAW] : utf8(String(v)));

function hex2(n) {
  return (n < 16 ? '0' : '') + n.toString(16);
}
function ansiQuote(bytes) {
  let s = "$'";
  for (const b of bytes) s += '\\x' + hex2(b);
  return s + "'";
}

// ---------------------------------------------------------------- runner
