const fs=require("fs");
let s=fs.readFileSync("/tmp/fuzz1.mjs","utf8");
const guard = `      if (isNegativeInt(v)) throw new Error("negative int generated: " + JSON.stringify(v));`;
s = s.split("\n").map((l)=> /negative int generated/.test(l) ? guard : l).join("\n");
// inject the helper right before the guard section
s = s.replace("// ---------------------------------------------------------------- guard",
`// ---------------------------------------------------------------- guard
// True only for strings Python int() would turn into a value < 0 (the reference
// binary loops forever on those, so they must never be generated).
const WS = new Set(UNI_WS_CP);
function isNegativeInt(v) {
  const cps = [...v].map((c) => c.codePointAt(0));
  let i = 0, j = cps.length;
  while (i < j && WS.has(cps[i])) i++;
  while (j > i && WS.has(cps[j - 1])) j--;
  if (i >= j || cps[i] !== 0x2d) return false;
  i++;
  let digits = "";
  let prevDigit = false;
  for (let k = i; k < j; k++) {
    const cp = cps[k];
    if (cp === 0x5f) { if (!prevDigit) return false; prevDigit = false; continue; }
    const d = decVal(cp);
    if (d < 0) return false;
    digits += String(d); prevDigit = true;
  }
  if (!prevDigit || digits === "") return false;
  return BigInt(digits) > 0n;
}
function decVal(cp) {
  const starts = [48, 1632, 1776, 1984, 2406, 2534, 2662, 2790, 2918, 3046, 3174,
    3302, 3430, 3558, 3664, 3792, 3872, 4160, 4240, 6112, 6160, 6470, 6608, 6784,
    6800, 6992, 7088, 7232, 7248, 42528, 43216, 43264, 43472, 43504, 43600, 44016,
    65296];
  for (const st of starts) if (cp >= st && cp < st + 10) return cp - st;
  return -1;
}`);
fs.writeFileSync("/tmp/fuzz1.mjs", s);
